import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        sc.nextLine(); // read and ignore the first line
        String s = sc.nextLine();

        int maxLen = 0;
        int count = 0;
        int index = 0;
        int lastIdx = 0;

        while (index < s.lastIndexOf(')')) {
            int openIdx = s.indexOf('(', index);
            int closeIdx = s.indexOf(')', openIdx);
            String segment = s.substring(lastIdx, openIdx);
            StringTokenizer st = new StringTokenizer(segment, "_");
            while (st.hasMoreTokens()) {
                int len = st.nextToken().length();
                if (len > maxLen) maxLen = len;
            }
            String inside = s.substring(openIdx + 1, closeIdx);
            StringTokenizer innerSt = new StringTokenizer(inside, "_");
            while (innerSt.hasMoreTokens()) {
                String token = innerSt.nextToken();
                if (!token.isEmpty()) count++;
            }
            lastIdx = closeIdx + 1;
            index = closeIdx;
        }

        String tail = s.substring(lastIdx);
        StringTokenizer tailSt = new StringTokenizer(tail, "_");
        while (tailSt.hasMoreTokens()) {
            int len = tailSt.nextToken().length();
            if (len > maxLen) maxLen = len;
        }

        System.out.println(maxLen + " " + count);
    }
}
