#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string dummy;
    getline(cin, dummy); // read and ignore the first line
    string s;
    getline(cin, s);

    int maxLen = 0;
    int count = 0;
    size_t index = 0;
    size_t lastIdx = 0;

    while (true) {
        size_t openIdx = s.find('(', index);
        if (openIdx == string::npos) break;
        size_t closeIdx = s.find(')', openIdx);
        if (closeIdx == string::npos) break;

        string segment = s.substr(lastIdx, openIdx - lastIdx);
        istringstream segmentStream(segment);
        string token;
        while (getline(segmentStream, token, '_')) {
            if (!token.empty()) {
                int len = (int)token.length();
                if (len > maxLen) maxLen = len;
            }
        }

        string inside = s.substr(openIdx + 1, closeIdx - openIdx - 1);
        istringstream insideStream(inside);
        while (getline(insideStream, token, '_')) {
            if (!token.empty()) {
                count++;
            }
        }

        lastIdx = closeIdx + 1;
        index = closeIdx + 1;
    }

    string tail = s.substr(lastIdx);
    istringstream tailStream(tail);
    string tailToken;
    while (getline(tailStream, tailToken, '_')) {
        if (!tailToken.empty()) {
            int len = (int)tailToken.length();
            if (len > maxLen) maxLen = len;
        }
    }

    cout << maxLen << " " << count << "\n";

    return 0;
}
